import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';
import '../theme/colors.dart';

/// TOUTES les icônes du site (components/Icons.js), converties telles
/// quelles en SVG : mêmes tracés, même épaisseur de trait. À utiliser pour
/// que l'application soit identique au site.
///
///   SiteIcon('IconCamera', size: 14, color: TytoColors.encre)
///   SiteIcon.espece('chat', size: 14)      // = SpeciesIcon du site
///   SiteIcon.evenement('vaccin', size: 16) // = EventIcon du site
///
/// Noms disponibles : voir la table [siteIcons] ci-dessous.
class SiteIcon extends StatelessWidget {
  final String name;
  final double size;
  final Color? color;
  const SiteIcon(this.name, {super.key, this.size = 18, this.color});

  factory SiteIcon.espece(String species, {double size = 18, Color? color}) {
    final cle = 'Species_' + species;
    return SiteIcon(siteIcons.containsKey(cle) ? cle : 'IconPaw', size: size, color: color);
  }

  factory SiteIcon.evenement(String type, {double size = 18, Color? color}) {
    final cle = 'Event_' + type;
    return SiteIcon(siteIcons.containsKey(cle) ? cle : 'Event_autre', size: size, color: color);
  }

  @override
  Widget build(BuildContext context) {
    final svg = siteIcons[name] ?? siteIcons['IconPaw']!;
    return SvgPicture.string(
      svg,
      width: size,
      height: size,
      colorFilter: ColorFilter.mode(color ?? TytoColors.lune, BlendMode.srcIn),
    );
  }
}

